{
  "assistantProvider": {
    "model": {
      "modelProviderName": "{{modelProviderName}}",
      "template": {
        "prompt": [
          {
            "role": "system",
            "content": "You are a helpful voice assistant."
          }
        ]
      },
      "assistantModelOptions": [
        {
          "key": "temperature",
          "value": "0.7"
        },
        {
          "key": "max_tokens",
          "value": "512"
        }
      ]
    }
  },
  "description": "Assistant created from the Postman collection.",
  "visibility": "private",
  "language": "en",
  "source": "postman",
  "sourceIdentifier": "{{sourceIdentifier}}",
  "tags": [
    "postman",
    "assistant-api"
  ],
  "name": "Postman Assistant"
}

{
  "assistantId": "{{assistantId}}",
  "configurationType": "analysis",
  "provider": "endpoint",
  "enabled": true,
  "options": [
    {
      "key": "name",
      "value": "Post-call conversation analysis"
    },
    {
      "key": "description",
      "value": "Summarize the completed conversation"
    },
    {
      "key": "execution_priority",
      "value": "0"
    },
    {
      "key": "endpoint_id",
      "value": "{{analysisEndpointId}}"
    },
    {
      "key": "endpoint_version",
      "value": "latest"
    },
    {
      "key": "endpoint_parameters",
      "value": "{\"conversation.messages\":\"messages\",\"assistant.name\":\"assistantName\"}"
    },
    {
      "key": "analysis.condition",
      "value": "[{\"key\":\"conversation_mode\",\"condition\":\"=\",\"value\":\"voice\"}]"
    }
  ]
}

{
  "configurationType": "analysis",
  "provider": "endpoint",
  "enabled": true,
  "options": [
    {
      "key": "name",
      "value": "Updated conversation analysis"
    },
    {
      "key": "description",
      "value": "Analyze voice and text conversations"
    },
    {
      "key": "execution_priority",
      "value": "3"
    },
    {
      "key": "endpoint_id",
      "value": "{{analysisEndpointId}}"
    },
    {
      "key": "endpoint_version",
      "value": "latest"
    },
    {
      "key": "endpoint_parameters",
      "value": "{\"conversation.id\":\"conversationId\",\"assistant.name\":\"assistantName\"}"
    },
    {
      "key": "analysis.condition",
      "value": "[{\"key\":\"conversation_mode\",\"condition\":\"=\",\"value\":\"text\"}]"
    }
  ]
}

{
  "assistantId": "{{assistantId}}",
  "greeting": "Hello, how can I help you today?",
  "greetingInterruptible": true,
  "mistake": "Sorry, I did not catch that.",
  "unclearInputTimeout": 4,
  "unclearInputMessage": "Could you repeat that?",
  "idealTimeout": 30,
  "idealTimeoutBackoff": 2,
  "idealTimeoutMessage": "Are you still there?",
  "maxSessionDuration": 300,
  "inputAudio": {
    "audioType": "input",
    "audioProvider": "{{sttProviderName}}",
    "status": "ACTIVE",
    "audioOptions": [
      {
        "key": "language",
        "value": "en-US"
      }
    ]
  },
  "outputAudio": {
    "audioType": "output",
    "audioProvider": "{{ttsProviderName}}",
    "status": "ACTIVE",
    "audioOptions": [
      {
        "key": "voice",
        "value": "default"
      }
    ]
  }
}

